// A local chain for the integration tests: an ephemeral Anvil, the contracts deployed from the
// generated bytecode, and the escrow actions.
import { spawn } from "node:child_process";
import { once } from "node:events";
import { createInterface } from "node:readline";

import {
  createTestClient,
  http,
  maxUint256,
  parseEventLogs,
  publicActions,
  walletActions,
  type Address,
  type Hash,
  type LocalAccount,
  type TransactionReceipt,
} from "viem";
import { privateKeyToAccount } from "viem/accounts";
import { foundry } from "viem/chains";

import type { Deployment } from "../../src/deployment.js";
import {
  escrowAbi,
  escrowBytecode,
  mockErc20Abi,
  mockErc20Bytecode,
} from "../../src/generated/contracts.js";

/** Anvil's default accounts 0 and 1. Their keys are public: only for local chains. */
export const alice = privateKeyToAccount(
  "0xac0974bec39a17e36ba4a6b4d238ff944bacb478cbed5efcae784d7bf4f2ff80",
);
export const bob = privateKeyToAccount(
  "0x59c6995e998f97a5a0044966f0945389dc9e86dae88c7a8412f4603b6b78690d",
);

/** The defaults of contracts/script/Deploy.s.sol: 2 hours and 7 days. */
export const CANCEL_WINDOW = 7_200n;
export const TTL = 604_800n;

export const ONE_TOKEN = 10n ** 18n;

/** Escrow.Status, in declaration order. */
export const ONCHAIN_STATUS = [
  "None",
  "Pending",
  "Released",
  "Rejected",
  "CancelledBySender",
  "Expired",
] as const;

function createClient(url: string) {
  return createTestClient({
    chain: foundry,
    mode: "anvil",
    transport: http(url),
    pollingInterval: 20,
    // Tests mine blocks and read the head right away: a cached block number would be stale.
    cacheTime: 0,
  })
    .extend(publicActions)
    .extend(walletActions);
}

export type TestClient = ReturnType<typeof createClient>;

export interface Anvil {
  url: string;
  client: TestClient;
  stop: () => Promise<void>;
}

/** Starts Anvil on a free port. `args` are extra command-line flags. */
export async function startAnvil(args: string[] = []): Promise<Anvil> {
  const child = spawn("anvil", ["--port", "0", ...args], { stdio: ["ignore", "pipe", "inherit"] });
  const lines = createInterface({ input: child.stdout });
  try {
    const url = await new Promise<string>((resolve, reject) => {
      lines.on("line", (line) => {
        const address = /^Listening on (\S+)$/.exec(line)?.[1];
        if (address) resolve(`http://${address}`);
      });
      child.once("error", reject);
      child.once("exit", (code) => {
        reject(new Error(`anvil exited with code ${String(code)}`));
      });
    });
    lines.close();
    // Anvil logs every request: keep draining its output so that it never blocks on a full pipe.
    child.stdout.resume();
    return {
      url,
      client: createClient(url),
      stop: async () => {
        if (child.exitCode !== null || child.signalCode !== null) return;
        child.kill();
        await once(child, "exit");
      },
    };
  } catch (error) {
    child.kill();
    throw error;
  }
}

/** Waits for the transaction and fails if it reverted. */
export async function mined(client: TestClient, hash: Hash): Promise<TransactionReceipt> {
  const receipt = await client.waitForTransactionReceipt({ hash });
  if (receipt.status !== "success") throw new Error(`Transaction ${hash} reverted`);
  return receipt;
}

function deployedAddress(receipt: TransactionReceipt): Address {
  if (!receipt.contractAddress) throw new Error(`${receipt.transactionHash} deployed nothing`);
  return receipt.contractAddress.toLowerCase() as Address;
}

/**
 * Deploys the escrow and a mock token like Deploy.s.sol does, and gives alice and bob tokens and an
 * unlimited allowance for the escrow. Returns what the deployments file would contain.
 */
export async function deployContracts(client: TestClient): Promise<Deployment> {
  const start = await client.getBlock();
  const escrow = deployedAddress(
    await mined(
      client,
      await client.deployContract({
        account: alice,
        abi: escrowAbi,
        bytecode: escrowBytecode,
        args: [CANCEL_WINDOW, TTL],
      }),
    ),
  );
  const token = deployedAddress(
    await mined(
      client,
      await client.deployContract({
        account: alice,
        abi: mockErc20Abi,
        bytecode: mockErc20Bytecode,
      }),
    ),
  );
  for (const account of [alice, bob]) {
    await mined(
      client,
      await client.writeContract({
        account,
        address: token,
        abi: mockErc20Abi,
        functionName: "mint",
        args: [account.address, 1_000_000n * ONE_TOKEN],
      }),
    );
    await mined(
      client,
      await client.writeContract({
        account,
        address: token,
        abi: mockErc20Abi,
        functionName: "approve",
        args: [escrow, maxUint256],
      }),
    );
  }
  return {
    chainId: foundry.id,
    escrow,
    token,
    cancelWindow: Number(CANCEL_WINDOW),
    ttl: Number(TTL),
    startBlock: start.number,
    startBlockHash: start.hash.toLowerCase() as Hash,
  };
}

export interface CreatedEscrow {
  id: bigint;
  receipt: TransactionReceipt;
}

export async function createEscrow(
  client: TestClient,
  deployment: Deployment,
  sender: LocalAccount,
  beneficiary: Address,
  amount = ONE_TOKEN,
): Promise<CreatedEscrow> {
  const receipt = await mined(
    client,
    await client.writeContract({
      account: sender,
      address: deployment.escrow,
      abi: escrowAbi,
      functionName: "createEscrow",
      args: [deployment.token, beneficiary, amount],
    }),
  );
  const [created] = parseEventLogs({
    abi: escrowAbi,
    eventName: "EscrowCreated",
    logs: receipt.logs,
  });
  if (!created) throw new Error(`${receipt.transactionHash} created no escrow`);
  return { id: created.args.id, receipt };
}

export type EscrowAction = "cancel" | "confirm" | "reject" | "recoverExpired";

export async function act(
  client: TestClient,
  deployment: Deployment,
  account: LocalAccount,
  action: EscrowAction,
  id: bigint,
): Promise<TransactionReceipt> {
  return mined(
    client,
    await client.writeContract({
      account,
      address: deployment.escrow,
      abi: escrowAbi,
      functionName: action,
      args: [id],
    }),
  );
}

/**
 * Creates `count` escrows, alternating the direction, and resolves three out of four: confirmed,
 * rejected, cancelled, left Pending. Mines `emptyBlocks` empty blocks after each escrow.
 */
export async function createActivity(
  client: TestClient,
  deployment: Deployment,
  count: number,
  emptyBlocks = 0,
): Promise<void> {
  for (let i = 0; i < count; i++) {
    const [sender, beneficiary] = i % 2 === 0 ? [alice, bob] : [bob, alice];
    const { id } = await createEscrow(client, deployment, sender, beneficiary.address);
    switch (i % 4) {
      case 0:
        await act(client, deployment, beneficiary, "confirm", id);
        break;
      case 1:
        await act(client, deployment, beneficiary, "reject", id);
        break;
      case 2:
        await act(client, deployment, sender, "cancel", id);
        break;
    }
    if (emptyBlocks > 0) await client.mine({ blocks: emptyBlocks });
  }
}
